import React from "react";
import {Box,styled} from '@mui/material';
import CloseFullscreenIcon from '@mui/icons-material/CloseFullscreen';
const Heading = styled(Box)`background: #00004d; display:flex; padding:9px 12px`
const Header = styled(Box)`display:flex; background:#060606;color:#AAAEBC; justify-content:space-between;font-weight:700`


const Editor = ()=>{
    return(
        <Box>
           <Header>
            <Heading>
                <Box component="span" 
                style={{
                    background:'red',
                    height:'20px',width:'20px',
                    display:'flex',
                    placeContent:'center',
                    borderRadius:'5px',
                    marginRight:'5px',
                    paddingBottom:'2px'}}>/
                </Box>
                Code
            </Heading>
            <CloseFullscreenIcon/>
           </Header>
        </Box>

    )
}

export default Editor;
